inline void to_string(const CertOrEncCert& value, std::ostream& out, int indent) {
    switch (value.kind) {
    case CertOrEncCert_kind::certificate:
        {
            out << "CertOrEncCert {";
            out << '\n' << std::string(static_cast<std::size_t>(indent + 1) * 4, ' ');
            out << "kind: certificate";
            out << '\n' << std::string(static_cast<std::size_t>(indent + 1) * 4, ' ');
            out << "value: ";
            to_string(std::get<0>(value.value), out, indent + 1);
            out << '\n' << std::string(static_cast<std::size_t>(indent) * 4, ' ') << '}';
            break;
        }
    case CertOrEncCert_kind::encryptedCert:
        {
            out << "CertOrEncCert {";
            out << '\n' << std::string(static_cast<std::size_t>(indent + 1) * 4, ' ');
            out << "kind: encryptedCert";
            out << '\n' << std::string(static_cast<std::size_t>(indent + 1) * 4, ' ');
            out << "value: ";
            to_string(std::get<1>(value.value), out, indent + 1);
            out << '\n' << std::string(static_cast<std::size_t>(indent) * 4, ' ') << '}';
            break;
        }
    }
}

